      String? // \"septic\", etc.\n  notes         String?\n  lat           Float?\n  lng           Float?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel ServiceType {\n  id        Int      @id @default(autoincrement())\n  code      String   @unique\n  name      String\n  isActive  Boolean  @default(true)\n  orders    Order[]\n  createdAt DateTime @default(now())\n}\n\nmodel Zone {\n  id          Int      @id @default(autoincrement())\n  name        String   @unique\n  basePrice   Int      @default(0)\n  perTonPrice Int      @default(0)\n  perM3Price  Int      @default(0)\n  perKmPrice  Int      @default(0)\n  orders      Order[]\n  createdAt   DateTime @default(now())\n}\n\nmodel AddOnService {\n  id          Int          @id @default(autoincrement())\n  code        String       @unique\n  name        String\n  priceType   PriceType    @default(FIXED)\n  priceValue  Int          @default(0)\n  isActive    Boolean      @default(true)\n  orderAddOns OrderAddOn[]\n  createdAt   DateTime     @default(now())\n}\n\nmodel TimeSlot {\n  id          Int      @id @default(autoincrement())\n  date        DateTime\n  startTime   String\n  endTime     String\n  capacity    Int      @default(3)\n  bookedCount Int      @default(0)\n  orders      Order[]\n  createdAt   DateTime @default(now())\n\n  @@unique([date, startTime, endTime])\n  @@index([date])\n}\n\nmodel Order {\n  id Int @id @default(autoincrement())\n\n  userId Int\n  user   User @relation(fields: [userId], references: [id])\n\n  // ── Жолооч ──\n  driverId   Int?\n  driver     Driver?   @relation(fields: [driverId], references: [id])\n  assignedAt DateTime? // Жолоочид хувиарлагдсан огноо\n\n  // ── Төлбөр ──\n  paid          Boolean   @default(false)\n  paidAt        DateTime? // Төлбөр төлөгдсөн огноо\n  paymentMethod String? // \"BANK_TRANSFER\" | \"CASH\"\n\n  date          String?\n  customerName  String?\n  customerPhone String?\n  notes         String?\n\n  // Wizard-аас ирэх энгийн field-үүд\n  serviceCode String   @default(\"BOHIR_US\")\n  district    String   @default(\"БЗД\")\n  unit        String   @default(\"тонн\")\n  timeSlot    String   @default(\"09-11\")\n  extras      String[]\n  totalPrice  Int      @default(0)\n\n  // ── Нүхний мэдээлэл — ШИНЭЭР НЭМСЭН ──\n  pitStatus String? // \"yes\" | \"no\" | \"unsure\"\n  pitType   String? // \"septic\" | \"pitToilet\" | \"tank\"\n\n  // Одоогийн field-үүд\n  address       String\n  volume        Float  @default(0)\n  volumeUnit    String @default(\"TON\")\n  lat           Float?\n  lng           Float?\n  status        String @default(\"PENDING\")\n  priceSubtotal Int    @default(0)\n  priceTotal    Int    @default(0)\n\n  // Relations\n  serviceTypeId Int?\n  serviceType   ServiceType? @relation(fields: [serviceTypeId], references: [id])\n\n  zoneId Int?\n  zone   Zone? @relation(fields: [zoneId], references: [id])\n\n  slotId Int?\n  slot   TimeSlot? @relation(fields: [slotId], references: [id])\n\n  addOns OrderAddOn[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel OrderAddOn {\n  orderId Int\n  addOnId Int\n\n  order Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  addOn AddOnService @relation(fields: [addOnId], references: [id], onDelete: Cascade)\n\n  @@id([orderId, addOnId])\n}\n\nmodel PasswordResetToken {\n  id        Int      @id @default(autoincrement())\n  token     String   @unique\n  userId    Int\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n}\n",
